// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Code by luk77 based on: 
// https://en.wikipedia.org/wiki/Tetrahedron
float hgsdfTetrahedronSoft(vec3 p, float r, float e)
{
    const vec3 v0 = normalize(vec3( 1,    1,    1));
    const vec3 v1 = normalize(vec3( 1,   -1,   -1));
    const vec3 v2 = normalize(vec3(-1,    1,   -1));
    const vec3 v3 = normalize(vec3(-1,   -1,    1));

    // alternative parameterization
    //const float s = 1.0 / sqrt(2.0);
    //const vec3 v0 = normalize(vec3( 1,   -s,    0));
    //const vec3 v1 = normalize(vec3(-1,   -s,    0));
    //const vec3 v2 = normalize(vec3( 0,    s,    1));
    //const vec3 v3 = normalize(vec3( 0,    s,   -1));

    float d = 0.0;
    d += pow(max(0.0, dot(p, v0)), e);
    d += pow(max(0.0, dot(p, v1)), e);
    d += pow(max(0.0, dot(p, v2)), e);
    d += pow(max(0.0, dot(p, v3)), e);

    return pow(d, 1./e) - r;
}
